<script lang="ts">
 import {adminUsersApi} from '#lib/api/admin/users.ts';import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {isStaffRole,requiresFacility} from '#lib/auth/roles.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import {Button} from '#lib/components/ui/button/index.ts';import {Input} from '#lib/components/ui/input/index.ts';import Modal from './Modal.svelte';import Feedback from './Feedback.svelte';import Subscription from './Subscription.svelte';import UserEditor from './UserEditor.svelte';import type {AdminUser,Role} from '#lib/types/user.ts';import type {MedicalFacility} from '#lib/types/clinic.ts';
 let users=$state<AdminUser[]>([]),roles=$state<Role[]>([]),facilities=$state<MedicalFacility[]>([]),loading=$state(true),error=$state(''),message=$state(''),revision=$state(0),search=$state(''),tab=$state('staff'),editor=$state(false),selected=$state<AdminUser|null>(null),action=$state<'roles'|'reset'|'delete'|null>(null),actionOpen=$state(false),roleIds=$state<string[]>([]),newPassword=$state(''),confirmPassword=$state(''),formError=$state(''),busy=$state(false),subscription=$state<MedicalFacility|null>(null),subscriptionOpen=$state(false);
 $effect(()=>{const r=revision;void r;let live=true;loading=true;error='';Promise.all([adminUsersApi.list(),adminUsersApi.getRoles(),adminClinicsApi.list()]).then(([u,r,f])=>{if(live){users=u;roles=r;facilities=f;}}).catch(e=>{if(live)error=apiMessage(e,'帳號與參考資料載入失敗');}).finally(()=>{if(live)loading=false;});return()=>{live=false;};});
 const filtered=$derived(users.filter(u=>(u.roles.some(isStaffRole)===(tab==='staff'))&&u.email.toLowerCase().includes(search.trim().toLowerCase())));const staffRoles=$derived(roles.filter(r=>r.is_active!==false&&isStaffRole(r.name)));
 function start(u:AdminUser,a:'roles'|'reset'|'delete'){selected=u;action=a;roleIds=roles.filter(r=>u.roles.includes(r.name)).map(r=>r.id);newPassword='';confirmPassword='';formError='';actionOpen=true;}
 async function perform(e?:SubmitEvent){e?.preventDefault();if(!selected)return;formError='';if(action==='roles'&&roles.some(r=>roleIds.includes(r.id)&&requiresFacility(r.name))&&!selected.facility_id){formError='院所角色必須先綁定院所，請先編輯帳號。';return;}if(action==='reset'&&newPassword!==confirmPassword){formError='兩次新密碼不一致';return;}busy=true;try{if(action==='roles')await adminUsersApi.setUserRoles(selected.id,roleIds);else if(action==='reset')await adminUsersApi.resetPassword(selected.id,newPassword);else if(action==='delete')await adminUsersApi.delete(selected.id);actionOpen=false;message=action==='reset'?'密碼已重設':'帳號設定已更新';revision++;}catch(e){formError=apiMessage(e,'帳號操作失敗');}finally{busy=false;}}
</script>
<div class="space-y-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-semibold">使用者管理</h1><p class="mt-1 text-sm text-muted-foreground">管理後台員工、院所綁定與民眾會員。</p></div>{#if tab==='staff'}<Button disabled={loading||!!error} onclick={()=>{selected=null;editor=true;}}>新增員工帳號</Button>{/if}</div><div class="flex flex-wrap gap-3"><Button variant={tab==='staff'?'default':'outline'} onclick={()=>tab='staff'}>後台員工（{users.filter(u=>u.roles.some(isStaffRole)).length}）</Button><Button variant={tab==='patient'?'default':'outline'} onclick={()=>tab='patient'}>民眾會員（{users.filter(u=>!u.roles.some(isStaffRole)).length}）</Button><Input class="max-w-sm" aria-label="搜尋帳號" placeholder="搜尋電子郵件" bind:value={search}/></div><Feedback {error} {message}/>{#if error}<Button variant="outline" onclick={()=>revision++}>重試使用者列表</Button>{/if}{#if loading}<p role="status">載入使用者中…</p>{:else if !error}<ul class="divide-y rounded-2xl border bg-card">{#each filtered as u (u.id)}<li class="space-y-3 p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><h2 class="break-all font-semibold">{u.email}</h2><p class="mt-1 text-sm text-muted-foreground">{u.is_active?'啟用':'停用'} · {u.phone_number||'電話未填'} · {u.facility_id?facilities.find(f=>f.id===u.facility_id)?.name??'未知院所':'未綁定院所'}</p><p class="mt-1 text-xs text-muted-foreground">{u.roles.map(r=>roles.find(x=>x.name===r)?.display_name??r).join('、')||'無角色'} · 最近登入 {u.last_login?new Date(u.last_login).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):'尚未登入'} · 就診人 {u.member_patients_count??0} 位</p></div><div class="flex flex-wrap gap-2"><Button size="sm" variant="outline" onclick={()=>{selected=u;editor=true;}}>編輯帳號</Button>{#if tab==='staff'}<Button size="sm" variant="outline" onclick={()=>start(u,'roles')}>管理角色</Button>{/if}<Button size="sm" variant="outline" onclick={()=>start(u,'reset')}>重設密碼</Button>{#if u.facility_id}<Button size="sm" variant="outline" onclick={()=>{subscription=facilities.find(f=>f.id===u.facility_id)??null;subscriptionOpen=!!subscription;}}>院所訂閱／續約</Button>{/if}<Button size="sm" variant="ghost" onclick={()=>start(u,'delete')}>刪除帳號</Button></div></div></li>{:else}<li class="p-8 text-center text-muted-foreground">沒有符合的帳號。</li>{/each}</ul>{/if}</div>
{#if editor}<UserEditor bind:open={editor} user={selected} roles={staffRoles} {facilities} onSaved={()=>{revision++;message='帳號已儲存';}}/>{/if}
<Modal bind:open={actionOpen} title={action==='roles'?'管理角色':action==='reset'?'重設密碼':'刪除帳號'} description={(selected?.email??'')+(action==='delete'?'・刪除後無法復原。':'')} {busy}><form onsubmit={perform} class="space-y-4"><Feedback error={formError}/>{#if action==='roles'}<fieldset disabled={busy} class="space-y-3">{#each staffRoles as r (r.id)}<label><input type="checkbox" value={r.id} bind:group={roleIds}/>{r.display_name}</label>{/each}</fieldset>{:else if action==='reset'}<fieldset disabled={busy} class="space-y-4"><label>新密碼<input type="password" bind:value={newPassword} minlength="8" autocomplete="new-password" required/></label><label>確認新密碼<input type="password" bind:value={confirmPassword} minlength="8" autocomplete="new-password" required/></label></fieldset>{/if}<div class="flex justify-end gap-2"><Button variant="outline" disabled={busy} onclick={()=>actionOpen=false}>取消</Button><Button type="submit" variant={action==='delete'?'destructive':'default'} disabled={busy}>{action==='delete'?'確認刪除帳號':action==='reset'?'確認重設密碼':'儲存角色'}</Button></div></form></Modal>
{#if subscription}<Modal bind:open={subscriptionOpen} title="院所訂閱與續約" description={subscription.name}><Subscription facility={subscription} onUpdated={f=>{subscription=f;facilities=facilities.map(x=>x.id===f.id?f:x);}}/></Modal>{/if}
